create extension if not exists "pgcrypto";
create table users (id uuid primary key default gen_random_uuid(), name varchar(120) not null, username varchar(60) unique not null, email varchar(255) unique not null, password_hash text not null, role varchar(10) not null default 'user' check(role in ('user','admin')), created_at timestamptz default now());
create table destinations (id uuid primary key default gen_random_uuid(), name varchar(160) not null, slug varchar(180) unique not null, description text not null, location varchar(180) not null, category varchar(40) not null, price integer not null check(price>0), image_url text not null, rating numeric(2,1) not null default 4.5, opening_hours varchar(100), facilities jsonb default '[]', created_at timestamptz default now(), updated_at timestamptz default now());
create table bookings (id uuid primary key default gen_random_uuid(), user_id uuid not null references users(id) on delete cascade, destination_id uuid not null references destinations(id), visit_date date not null, quantity integer not null check(quantity>0), price_per_ticket integer not null, total_price integer not null, status varchar(12) not null default 'pending' check(status in ('pending','paid','cancelled','used')), created_at timestamptz default now());
create table tickets (id uuid primary key default gen_random_uuid(), booking_id uuid unique not null references bookings(id) on delete cascade, ticket_code varchar(24) unique not null, qr_token varchar(100) unique not null, status varchar(12) not null default 'valid' check(status in ('valid','used','cancelled')), used_at timestamptz, created_at timestamptz default now());
